response_text:
**Here's a production-ready Terraform configuration for cross-account S3 and RDS disaster recovery replication.**

### 1. Main Configuration (`main.tf`)

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider for the primary account (source)
provider "aws" {
  alias  = "primary"
  region = var.primary_region
}

# Provider for the DR account (destination)
provider "aws" {
  alias  = "dr"
  region = var.dr_region
  # Assumes you have a role in the DR account that this Terraform can assume
  assume_role {
    role_arn = "arn:aws:iam::${var.dr_account_id}:role/TerraformDRRole"
  }
}

# Data source to get current account ID in primary
data "aws_caller_identity" "primary" {
  provider = aws.primary
}

# Data source to get current account ID in DR (for validation)
data "aws_caller_identity" "dr" {
  provider = aws.dr
}
```

### 2. S3 Cross-Account Replication (`s3-replication.tf`)

```hcl
# S3 Bucket Replication Role (created in PRIMARY account)
resource "aws_iam_role" "s3_replication_role" {
  provider = aws.primary
  name     = "s3-cross-account-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication_policy" {
  provider = aws.primary
  name     = "s3-replication-policy"
  role     = aws_iam_role.s3_replication_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetReplicationConfiguration"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${var.dr_bucket_prefix}-*/*"
      }
    ]
  })
}

# Example: Replicated S3 Buckets
module "replicated_buckets" {
  source   = "./modules/s3-replicated-bucket"
  for_each = var.s3_buckets_to_replicate
  providers = {
    aws.primary = aws.primary
    aws.dr      = aws.dr
  }

  bucket_name         = each.key
  primary_account_id  = data.aws_caller_identity.primary.account_id
  dr_account_id       = var.dr_account_id
  dr_region           = var.dr_region
  replication_role_arn = aws_iam_role.s3_replication_role.arn
  versioning_enabled  = true
  object_lock_enabled = each.value.object_lock_enabled
  tags                = each.value.tags
}
```

### 3. RDS Cross-Account Snapshot Sharing + Copy (`rds-dr.tf`)

```hcl
# RDS Automated Snapshot Sharing + Copy to DR Account
module "rds_dr" {
  source   = "./modules/rds-dr"
  for_each = var.rds_instances_to_protect
  providers = {
    aws.primary = aws.primary
    aws.dr      = aws.dr
  }

  db_instance_identifier = each.key
  dr_account_id          = var.dr_account_id
  dr_region              = var.dr_region
  retention_days         = var.rds_snapshot_retention_days
  copy_tags              = true
  kms_key_arn_dr         = aws_kms_key.dr_rds.arn
  tags                   = each.value.tags
}

# KMS Key in DR account for RDS snapshots
resource "aws_kms_key" "dr_rds" {
  provider    = aws.dr
  description = "KMS key for cross-account RDS snapshots"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = { AWS = "arn:aws:iam::${var.dr_account_id}:root" }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow primary account to use this key"
        Effect = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.primary.account_id}:root" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}
```

### 4. Variables (`variables.tf`)

```hcl
variable "primary_region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "dr_region" {
  description = "Disaster Recovery region"
  type        = string
  default     = "us-west-2"
}

variable "dr_account_id" {
  description = "AWS Account ID for the DR account"
  type        = string
}

variable "s3_buckets_to_replicate" {
  description = "Map of S3 buckets to replicate"
  type = map(object({
    object_lock_enabled = optional(bool, false)
    tags                = optional(map(string), {})
  }))
  default = {}
}

variable "rds_instances_to_protect" {
  description = "Map of RDS instances to protect via snapshot replication"
  type = map(object({
    tags = optional(map(string), {})
  }))
  default = {}
}

variable "rds_snapshot_retention_days" {
  description = "How many days to retain copied snapshots in DR"
  type        = number
  default     = 30
}
```

### 5. Example Usage (`terraform.tfvars`)

```hcl
dr_account_id = "123456789012"
primary_region = "us-east-1"
dr_region      = "us-west-2"

s3_buckets_to_replicate = {
  "my-app-data" = {
    object_lock_enabled = true
    tags = { Environment = "prod", Criticality = "high" }
  },
  "my-app-logs" = {}
}

rds_instances_to_protect = {
  "prod-postgres" = {
    tags = { Environment = "prod" }
  }
}
```

### 6. Recommended Module Structure

Create these modules:
- `modules/s3-replicated-bucket` — creates bucket + replication config in primary + destination bucket in DR
- `modules/rds-dr` — creates EventBridge rule + Lambda to copy snapshots + share them cross-account

---

**Important Notes:**

1. **Permissions**: The DR account needs an IAM role (`TerraformDRRole`) that your Terraform can assume.
2. **S3 Replication** works for new objects only (existing objects need one-time copy or S3 Batch Operations).
3. **RDS** uses a Lambda triggered by EventBridge to copy automated snapshots to the DR account.
4. Consider adding:
   - AWS Backup (recommended for enterprise)
   - Cross-region KMS keys
   - Monitoring and alerting on replication health
   - S3 Batch Operations for initial backfill

